// ──────────────────────────── tests ──────────────────────────────────────

test('returns the value when the variable is set', () => {
  eq(readEnv({ PORT: '8080' }, 'PORT'), '8080');
});

test('falls back when the variable is missing', () => {
  eq(readEnv({}, 'HOST', 'localhost'), 'localhost');
});

test('treats an empty string as not set', () => {
  eq(readEnv({ HOST: '' }, 'HOST', 'localhost'), 'localhost');
});

test('throws with the variable name when required and missing', () => {
  eq(readEnv({ API_TOKEN: 'abc' }, 'API_TOKEN'), 'abc');
  throws(() => readEnv({}, 'API_TOKEN'), 'API_TOKEN');
});

test('readNumberEnv parses digits and honours the fallback', () => {
  eq(readNumberEnv({ PORT: '8080' }, 'PORT', 3000), 8080);
  eq(readNumberEnv({}, 'PORT', 3000), 3000);
});

test('readNumberEnv throws on junk instead of falling back', () => {
  eq(readNumberEnv({ PORT: '1' }, 'PORT'), 1);
  throws(() => readNumberEnv({ PORT: 'eighty' }, 'PORT', 3000), 'PORT');
});

test('readBoolEnv understands the usual spellings', () => {
  eq(readBoolEnv({ D: 'yes' }, 'D'), true);
  eq(readBoolEnv({ D: 'TRUE' }, 'D'), true);
  eq(readBoolEnv({ D: 'off' }, 'D'), false);
  eq(readBoolEnv({}, 'D', false), false);
  throws(() => readBoolEnv({ D: 'maybe' }, 'D'));
});

test('works against the real process.env', () => {
  eq(readEnv(process.env, 'JSTRAIN_NOT_SET_XYZ', 'default'), 'default');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('collects bare words as positionals', () => {
  eq(parseArgs(['build', 'src']), {
    flags: {},
    positionals: ['build', 'src'],
  });
});

test('reads --key=value', () => {
  eq(parseArgs(['--out=dist']).flags, { out: 'dist' });
});

test('reads --key value and consumes the value', () => {
  eq(parseArgs(['--out', 'dist']), { flags: { out: 'dist' }, positionals: [] });
});

test('a --key with nothing to consume becomes true', () => {
  eq(parseArgs(['--watch']).flags, { watch: true });
  eq(parseArgs(['--watch', '--quiet']).flags, { watch: true, quiet: true });
});

test('--no-key becomes false', () => {
  eq(parseArgs(['--no-cache']).flags, { cache: false });
});

test('expands a short cluster like -vfz', () => {
  eq(parseArgs(['-vfz']).flags, { v: true, f: true, z: true });
});

test('-- stops flag parsing', () => {
  eq(parseArgs(['run', '--', '--not-a-flag', '-x']), {
    flags: {},
    positionals: ['run', '--not-a-flag', '-x'],
  });
});

test('parses a realistic command line', () => {
  eq(parseArgs(['deploy', '--env=prod', '--dry-run', '-v', 'web', '--tag', 'v2']), {
    flags: { env: 'prod', 'dry-run': true, v: true, tag: 'v2' },
    positionals: ['deploy', 'web'],
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('joins parts with the platform separator', () => {
  eq(joinParts('src', 'lib', 'index.js'), ['src', 'lib', 'index.js'].join(path.sep));
});

test('collapses .. while joining', () => {
  eq(joinParts('src', 'lib', '..', 'index.js'), path.join('src', 'index.js'));
});

test('fileName is the last segment', () => {
  eq(fileName('src/lib/index.js'), 'index.js');
  eq(fileName(path.join('src', 'lib', 'index.js')), 'index.js');
});

test('fileStem drops only the last extension', () => {
  eq(fileStem('src/report.final.pdf'), 'report.final');
});

test('extension is lowercase and has no dot', () => {
  eq(extension('photo.JPG'), 'jpg');
  eq(extension('src/lib/index.js'), 'js');
});

test('a file with no extension has an empty extension', () => {
  eq(extension('Makefile'), '');
  eq(fileStem('Makefile'), 'Makefile');
});

test('a dotfile is all name and no extension', () => {
  eq(extension('.gitignore'), '');
  eq(fileStem('.gitignore'), '.gitignore');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('changeExtension swaps the extension', () => {
  eq(changeExtension(path.join('src', 'app.ts'), '.js'), path.join('src', 'app.js'));
});

test('changeExtension accepts an extension without a dot', () => {
  eq(changeExtension('notes.md', 'txt'), 'notes.txt');
});

test('changeExtension adds an extension when there was none', () => {
  eq(changeExtension('LICENSE', '.txt'), 'LICENSE.txt');
});

test('toPosix normalises separators for display', () => {
  eq(toPosix(path.join('src', 'lib', 'index.js')), 'src/lib/index.js');
});

test('relativeTo walks up and back down', () => {
  eq(
    relativeTo(path.resolve('/repo/src'), path.resolve('/repo/docs/readme.md')),
    '../docs/readme.md'
  );
});

test('relativeTo is empty for the same directory', () => {
  eq(relativeTo(path.resolve('/repo'), path.resolve('/repo')), '');
});

test('isInside is true only for real descendants', () => {
  const parent = path.resolve('/repo/src');
  eq(isInside(parent, path.resolve('/repo/src/app/main.js')), true);
  eq(isInside(parent, path.resolve('/repo/docs/readme.md')), false);
  eq(isInside(parent, parent), false);
});

test('isInside is not fooled by a shared name prefix', () => {
  const parent = path.resolve('/repo/src');
  eq(isInside(parent, path.resolve('/repo/src-extra/a.js')), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('writes a file and reads it back', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'note.txt');
    await writeText(file, 'hello');
    eq(await readText(file), 'hello');
  });
});

test('readText returns a string, not a Buffer', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'note.txt');
    await writeText(file, 'hello');
    ok(typeof (await readText(file)) === 'string');
  });
});

test('writeText replaces the whole file', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'note.txt');
    await writeText(file, 'first');
    await writeText(file, 'second');
    eq(await readText(file), 'second');
  });
});

test('appendLine creates the file when it does not exist', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'log.txt');
    await appendLine(file, 'started');
    eq(await readText(file), 'started\n');
  });
});

test('appendLine adds to the end without clobbering', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'log.txt');
    await appendLine(file, 'one');
    await appendLine(file, 'two');
    eq(await readText(file), 'one\ntwo\n');
  });
});

test('readLines ignores the trailing newline', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'log.txt');
    await writeText(file, 'alpha\nbeta\n');
    eq(await readLines(file), ['alpha', 'beta']);
  });
});

test('reading a missing file rejects with ENOENT', async () => {
  await withTempDir(async (dir) => {
    await writeText(path.join(dir, 'here.txt'), 'x');
    await rejects(() => readText(path.join(dir, 'gone.txt')), 'ENOENT');
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('round trips an object through the file', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    await writeJson(file, { users: ['ada'], hits: 1 });
    eq(await readJson(file, null), { users: ['ada'], hits: 1 });
  });
});

test('writes pretty JSON ending in a newline', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    await writeJson(file, { hits: 1 });
    const raw = await fs.readFile(file, 'utf8');
    eq(raw, '{\n  "hits": 1\n}\n');
  });
});

test('returns the fallback when the file does not exist', async () => {
  await withTempDir(async (dir) => {
    eq(await readJson(path.join(dir, 'missing.json'), { users: [] }), { users: [] });
  });
});

test('invalid JSON rejects instead of falling back', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    await writeJson(file, { ok: true });
    await fs.writeFile(file, '{ not json at all', 'utf8');
    await rejects(() => readJson(file, { ok: false }));
  });
});

test('updateJson creates the file on the first call', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    await updateJson(file, (db) => ({ ...db, hits: (db.hits ?? 0) + 1 }));
    eq(await readJson(file, null), { hits: 1 });
  });
});

test('updateJson feeds the previous value to the updater', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    const bump = (db) => ({ ...db, hits: (db.hits ?? 0) + 1 });
    await updateJson(file, bump);
    await updateJson(file, bump);
    await updateJson(file, bump);
    eq(await readJson(file, null), { hits: 3 });
  });
});

test('updateJson returns exactly what it wrote', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    const returned = await updateJson(file, (db) => ({
      ...db,
      users: [...(db.users ?? []), 'ada'],
    }));
    eq(returned, { users: ['ada'] });
    eq(await readJson(file, null), returned);
    ok(typeof returned === 'object');
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('pathExists is false for something that is not there', async () => {
  await withTempDir(async (dir) => {
    eq(await pathExists(path.join(dir, 'nope.txt')), false);
  });
});

test('pathExists is true for a file and for a directory', async () => {
  await withTempDir(async (dir) => {
    await fs.writeFile(path.join(dir, 'a.txt'), 'x', 'utf8');
    eq(await pathExists(path.join(dir, 'a.txt')), true);
    eq(await pathExists(dir), true);
  });
});

test('ensureDir creates a nested chain in one call', async () => {
  await withTempDir(async (dir) => {
    const deep = path.join(dir, 'a', 'b', 'c');
    eq(await ensureDir(deep), deep);
    const stats = await fs.stat(deep);
    eq(stats.isDirectory(), true);
  });
});

test('ensureDir on an existing directory is a no-op', async () => {
  await withTempDir(async (dir) => {
    const target = path.join(dir, 'cache');
    await ensureDir(target);
    await fs.writeFile(path.join(target, 'keep.txt'), 'x', 'utf8');
    await ensureDir(target);
    eq(await fs.readFile(path.join(target, 'keep.txt'), 'utf8'), 'x');
  });
});

test('listByExtension returns matching names, sorted', async () => {
  await withTempDir(async (dir) => {
    await fs.writeFile(path.join(dir, 'todo.txt'), '', 'utf8');
    await fs.writeFile(path.join(dir, 'notes.txt'), '', 'utf8');
    await fs.writeFile(path.join(dir, 'app.js'), '', 'utf8');
    eq(await listByExtension(dir, '.txt'), ['notes.txt', 'todo.txt']);
  });
});

test('listByExtension skips directories, even file-shaped ones', async () => {
  await withTempDir(async (dir) => {
    await fs.writeFile(path.join(dir, 'real.txt'), '', 'utf8');
    await fs.mkdir(path.join(dir, 'archive.txt'));
    eq(await listByExtension(dir, '.txt'), ['real.txt']);
  });
});

test('listByExtension ignores case and an optional leading dot', async () => {
  await withTempDir(async (dir) => {
    await fs.writeFile(path.join(dir, 'README.TXT'), '', 'utf8');
    await fs.writeFile(path.join(dir, 'a.txt'), '', 'utf8');
    eq(await listByExtension(dir, 'txt'), ['README.TXT', 'a.txt']);
    eq(await listByExtension(dir, '.TXT'), ['README.TXT', 'a.txt']);
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('lists the files at the top level', async () => {
  await withTempDir(async (dir) => {
    await makeTree(dir, { 'a.txt': 'a', 'b.txt': 'b' });
    eq(await walkFiles(dir), ['a.txt', 'b.txt']);
  });
});

test('descends into subdirectories', async () => {
  await withTempDir(async (dir) => {
    await makeTree(dir, {
      'src/app.js': '',
      'src/lib/util.js': '',
      'docs/readme.md': '',
    });
    eq(await walkFiles(dir), ['docs/readme.md', 'src/app.js', 'src/lib/util.js']);
  });
});

test('paths are relative to the root and use forward slashes', async () => {
  await withTempDir(async (dir) => {
    await makeTree(dir, { 'src/lib/util.js': '' });
    eq(await walkFiles(dir), ['src/lib/util.js']);
  });
});

test('directories themselves are never listed', async () => {
  await withTempDir(async (dir) => {
    await makeTree(dir, { 'empty': null, 'src/deep': null, 'src/app.js': '' });
    eq(await walkFiles(dir), ['src/app.js']);
  });
});

test('an empty directory yields an empty list', async () => {
  await withTempDir(async (dir) => {
    eq(await walkFiles(dir), []);
  });
});

test('handles a three-level tree', async () => {
  await withTempDir(async (dir) => {
    await makeTree(dir, {
      'a/b/c/deep.txt': 'x',
      'a/b/mid.txt': 'x',
      'a/top.txt': 'x',
    });
    eq(await walkFiles(dir), ['a/b/c/deep.txt', 'a/b/mid.txt', 'a/top.txt']);
  });
});

test('countExtensions tallies the whole tree', async () => {
  await withTempDir(async (dir) => {
    await makeTree(dir, {
      'src/app.js': '',
      'src/lib/util.js': '',
      'docs/readme.md': '',
      'LICENSE': '',
    });
    eq(await countExtensions(dir), { '.js': 2, '.md': 1, '': 1 });
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('copies a single top-level file', async () => {
  await withTempDir(async (dir) => {
    const src = path.join(dir, 'src');
    const dest = path.join(dir, 'dest');
    await makeTree(src, { 'a.txt': 'alpha' });
    await copyTree(src, dest);
    eq(await fs.readFile(path.join(dest, 'a.txt'), 'utf8'), 'alpha');
  });
});

test('creates the destination directory when it is missing', async () => {
  await withTempDir(async (dir) => {
    const src = path.join(dir, 'src');
    const dest = path.join(dir, 'nested', 'dest');
    await makeTree(src, { 'a.txt': 'alpha' });
    await copyTree(src, dest);
    eq((await fs.stat(dest)).isDirectory(), true);
  });
});

test('reproduces a nested tree exactly', async () => {
  await withTempDir(async (dir) => {
    const src = path.join(dir, 'src');
    const dest = path.join(dir, 'dest');
    await makeTree(src, {
      'app.js': 'main',
      'lib/util.js': 'helper',
      'lib/deep/core.js': 'core',
    });
    await copyTree(src, dest);
    eq(await snapshot(dest), await snapshot(src));
  });
});

test('keeps UTF-8 content intact', async () => {
  await withTempDir(async (dir) => {
    const src = path.join(dir, 'src');
    const dest = path.join(dir, 'dest');
    await makeTree(src, { 'hi.txt': 'café 👋 naïve' });
    await copyTree(src, dest);
    eq(await fs.readFile(path.join(dest, 'hi.txt'), 'utf8'), 'café 👋 naïve');
  });
});

test('returns the number of files copied', async () => {
  await withTempDir(async (dir) => {
    const src = path.join(dir, 'src');
    const dest = path.join(dir, 'dest');
    await makeTree(src, {
      'a.txt': '1',
      'sub/b.txt': '2',
      'sub/deeper/c.txt': '3',
      'sub/empty': null,
    });
    eq(await copyTree(src, dest), 3);
  });
});

test('copies empty directories too', async () => {
  await withTempDir(async (dir) => {
    const src = path.join(dir, 'src');
    const dest = path.join(dir, 'dest');
    await makeTree(src, { 'logs': null, 'keep/me': null });
    eq(await copyTree(src, dest), 0);
    eq(await snapshot(dest), ['dir  keep', 'dir  keep/me', 'dir  logs']);
  });
});

test('overwrites a file that already exists in the destination', async () => {
  await withTempDir(async (dir) => {
    const src = path.join(dir, 'src');
    const dest = path.join(dir, 'dest');
    await makeTree(src, { 'a.txt': 'new' });
    await makeTree(dest, { 'a.txt': 'old', 'own.txt': 'mine' });
    await copyTree(src, dest);
    eq(await fs.readFile(path.join(dest, 'a.txt'), 'utf8'), 'new');
    eq(await fs.readFile(path.join(dest, 'own.txt'), 'utf8'), 'mine');
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('encodes a known string to base64', () => {
  eq(toBase64('hello'), 'aGVsbG8=');
});

test('round trips through base64', () => {
  const text = 'The quick brown fox.';
  eq(fromBase64(toBase64(text)), text);
});

test('encodes a known string to hex', () => {
  eq(toHex('hi'), '6869');
});

test('round trips through hex', () => {
  eq(fromHex(toHex('node')), 'node');
});

test('non-ASCII survives base64', () => {
  eq(toBase64('café'), 'Y2Fmw6k=');
  eq(fromBase64('Y2Fmw6k='), 'café');
});

test('an emoji survives a hex round trip', () => {
  eq(toHex('👋'), 'f09f918b');
  eq(fromHex('f09f918b'), '👋');
});

test('the empty string encodes to the empty string', () => {
  eq(toBase64(''), '');
  eq(toHex(''), '');
  eq(fromBase64(''), '');
  eq(fromHex(''), '');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('for plain ASCII, bytes and characters agree', () => {
  eq(byteLength('hello'), 5);
  eq(charCount('hello'), 5);
});

test('an accented character costs two bytes', () => {
  eq(byteLength('café'), 5);
  eq(charCount('café'), 4);
});

test('an emoji is four bytes, two UTF-16 units, one character', () => {
  eq(byteLength('👋'), 4);
  eq('👋'.length, 2);
  eq(charCount('👋'), 1);
});

test('joinBuffers concatenates into one buffer', () => {
  const joined = joinBuffers([Buffer.from('ab'), Buffer.from('cd')]);
  ok(Buffer.isBuffer(joined));
  eq(joined.toString('utf8'), 'abcd');
});

test('joinBuffers of nothing is an empty buffer', () => {
  eq(joinBuffers([]).length, 0);
});

test('truncateBytes returns the whole string when it fits', () => {
  eq(truncateBytes('hello', 99), 'hello');
  eq(truncateBytes('', 4), '');
});

test('truncateBytes cuts on a character boundary', () => {
  eq(truncateBytes('héllo', 3), 'hé');
  eq(truncateBytes('héllo', 2), 'h');
  eq(byteLength(truncateBytes('héllo', 4)), 4);
});

test('truncateBytes never splits an emoji', () => {
  eq(truncateBytes('a👋b', 3), 'a');
  eq(truncateBytes('a👋b', 5), 'a👋');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('splits a full URL into its parts', () => {
  eq(describeUrl('https://api.example.com:8443/v1/users?page=2&sort=name'), {
    protocol: 'https:',
    hostname: 'api.example.com',
    port: '8443',
    pathname: '/v1/users',
    query: { page: '2', sort: 'name' },
  });
});

test('the default port comes back as an empty string', () => {
  eq(describeUrl('https://example.com/').port, '');
  eq(describeUrl('http://example.com:3000/').port, '3000');
});

test('pathname is "/" when the URL has no path', () => {
  eq(describeUrl('https://example.com').pathname, '/');
  eq(describeUrl('https://example.com').query, {});
});

test('a bare path is not a URL', () => {
  eq(describeUrl('https://example.com/').protocol, 'https:');
  throws(() => describeUrl('/api/users'), 'Invalid URL');
});

test('queryToObject turns a query string into an object', () => {
  eq(queryToObject('page=2&sort=name'), { page: '2', sort: 'name' });
  eq(queryToObject('?page=2'), { page: '2' });
  eq(queryToObject(''), {});
});

test('repeated keys collapse into an array', () => {
  eq(queryToObject('tag=a&tag=b&page=1'), { tag: ['a', 'b'], page: '1' });
});

test('percent-encoding and + are decoded for you', () => {
  eq(queryToObject('q=hello+world&path=a%2Fb'), { q: 'hello world', path: 'a/b' });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('joins the base and the path', () => {
  eq(buildUrl('https://api.example.com', '/users'), 'https://api.example.com/users');
});

test('never produces a double slash', () => {
  eq(buildUrl('https://api.example.com/v1/', 'users'), 'https://api.example.com/v1/users');
  eq(buildUrl('https://api.example.com/v1/', '/users'), 'https://api.example.com/v1/users');
});

test('appends query params', () => {
  eq(
    buildUrl('https://api.example.com', '/users', { page: 2, sort: 'name' }),
    'https://api.example.com/users?page=2&sort=name'
  );
});

test('drops null and undefined params', () => {
  eq(
    buildUrl('https://api.example.com', '/users', { page: 2, q: null, x: undefined }),
    'https://api.example.com/users?page=2'
  );
});

test('repeats an array param', () => {
  eq(
    buildUrl('https://api.example.com', '/search', { tag: ['a', 'b'] }),
    'https://api.example.com/search?tag=a&tag=b'
  );
});

test('escapes values that need it', () => {
  eq(
    buildUrl('https://api.example.com', '/search', { q: 'red shoes', path: 'a/b' }),
    'https://api.example.com/search?q=red+shoes&path=a%2Fb'
  );
});

test('mergeParams overwrites one param and keeps the rest', () => {
  eq(
    mergeParams('https://x.dev/a?page=1&sort=name', { page: 3 }),
    'https://x.dev/a?page=3&sort=name'
  );
});

test('mergeParams removes a param set to null', () => {
  eq(mergeParams('https://x.dev/a?page=1&sort=name', { sort: null }), 'https://x.dev/a?page=1');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('matches the published sha256 of "abc"', () => {
  eq(sha256('abc'), 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
});

test('a digest is 64 lowercase hex characters', () => {
  const digest = sha256('anything at all');
  eq(digest.length, 64);
  ok(/^[0-9a-f]{64}$/.test(digest));
});

test('the same input always gives the same digest', () => {
  eq(sha256('deploy me'), sha256('deploy me'));
});

test('one changed character changes everything', () => {
  ok(sha256('version 1') !== sha256('version 2'));
});

test('a Buffer hashes the same as the string it holds', () => {
  eq(sha256(Buffer.from('abc', 'utf8')), sha256('abc'));
});

test('sameContent compares by digest', () => {
  eq(sameContent('the same text', 'the same text'), true);
  eq(sameContent('the same text', 'the same text!'), false);
});

test('isUuid accepts what randomUUID produces', () => {
  eq(isUuid(randomUUID()), true);
