  const emitter = new EventEmitter();
  setTimeout(() => emitter.emit('ready', 1), 0);
  eq(await waitForEvent(emitter, 'ready', 100), 1);
  await rejects(() => waitForEvent(emitter, 'never', 20), 'timed out');
