});

test('collectText joins string chunks', async () => {
  eq(await collectText(streamOf(['ab', 'cd', 'ef'])), 'abcdef');
});

test('collectText handles Buffer chunks', async () => {
  const stream = Readable.from([Buffer.from('ab'), Buffer.from('cd')]);
