  eq(matchGlob('data.txt', 'data0txt'), false);
  eq(matchGlob('a+b.txt', 'a+b.txt'), true);
  eq(matchGlob('a+b.txt', 'ab.txt'), false);
  eq(matchGlob('v(1).txt', 'v(1).txt'), true);
