  const target = fakeProcess();
  target.exit = spy(() => log.push('exit'));
  const uninstall = installShutdown(target, async () => {
    log.push('cleanup start');
    await sleep(10);
    log.push('cleanup done');
  });
  target.emit('SIGINT');
  await sleep(50);
  eq(log, ['cleanup start', 'cleanup done', 'exit']);
  uninstall();
});

